// --- Rusça morfoloji yardımcıları (İngilizce vocabulary.ts ile aynı yapıda) ---

function getTurkishPluralRu(tr: string): string {
  const base = tr.split(" /")[0].split(" (")[0].trim().split(" ")[0];
  if (!base) return tr + " lar";
  const vowels = base.toLowerCase().match(/[aeıioöuü]/g);
  const lastVowel = vowels ? vowels[vowels.length - 1] : "e";
  const isKalın = ["a","ı","o","u"].includes(lastVowel);
  return base + (isKalın ? "lar" : "ler");
}

const RU_TRANSLIT: Record<string,string> = {
  "а":"a","б":"b","в":"v","г":"g","д":"d","е":"ye","ё":"yo","ж":"zh","з":"z","и":"i","й":"y",
  "к":"k","л":"l","м":"m","н":"n","о":"o","п":"p","р":"r","с":"s","т":"t","у":"u","ф":"f",
  "х":"kh","ц":"ts","ч":"ch","ш":"sh","щ":"shch","ъ":"","ы":"y","ь":"","э":"e","ю":"yu","я":"ya"
};

function translitRu(word: string): string {
  return word.split("").map(c => RU_TRANSLIT[c] ?? c).join("").slice(0,24);
}

const IRREGULAR_PLURALS_RU: Record<string,string> = {
  "человек":"люди","ребёнок":"дети","ребенок":"дети","друг":"друзья","сын":"сыновья","брат":"братья",
  "дерево":"деревья","лист":"листья","стул":"стулья","время":"времена","имя":"имена","мать":"матери",
  "дочь":"дочери","яблоко":"яблоки","ухо":"уши","глаз":"глаза","дом":"дома","город":"города",
  "поезд":"поезда","вечер":"вечера","берег":"берега","голос":"голоса","лес":"леса","снег":"снега",
  "день":"дни","сон":"сны","озеро":"озёра","ведро":"вёдра","зерно":"зёрна","сестра":"сёстры",
  "звезда":"звёзды","слеза":"слёзы","весна":"вёсны","небо":"небеса","чудо":"чудеса","плечо":"плечи",
  "колено":"колени","крыло":"крылья","перо":"перья","звено":"звенья","ружьё":"ружья",
  "метро":"метро","такси":"такси","кино":"кино","кофе":"кофе","кафе":"кафе","пальто":"пальто",
  "радио":"радио","пианино":"пианино","шоссе":"шоссе","бюро":"бюро","резюме":"резюме",
  "меню":"меню","жюри":"жюри","цветок":"цветы"
};

function russianPlural(word: string): string | null {
  const irr = IRREGULAR_PLURALS_RU[word];
  if (irr) return irr;
  if (word.length < 3 || /\s|-/.test(word)) return null;
  const last = word[word.length - 1];
  const hard = "гкхжшчщ";
  if (last === "а") {
    const prev = word[word.length - 2];
    return word.slice(0,-1) + (hard.includes(prev) ? "и" : "ы");
  }
  if (last === "я") return word.slice(0,-1) + "и";
  if (last === "о") return word.slice(0,-1) + "а";
  // Zaten çoğul olanlar (данные, наличные) - çoğul üretme
  if (word.endsWith("ые")) return null;
  if (last === "е") {
    // İsimleşmiş sıfatlar: насекомое -> насекомые, мороженое -> мороженые
    if (word.endsWith("ое")) return word.slice(0,-2) + "ые";
    // -це: сердце -> сердца, солнце -> солнца
    if (word.endsWith("це")) return word.slice(0,-1) + "а";
    return word.slice(0,-1) + "я";
  }
  if (last === "ь") return word.slice(0,-1) + "и";
  if (last === "й") return word.slice(0,-1) + "и";
  if (last === "и" || last === "ы") return null;
  // Akıcı "е": -ец -> -цы (конец -> концы, палец -> пальцы), заяц -> зайцы, сосед -> соседи
  if (word.endsWith("ец")) return word === "палец" ? "пальцы" : word.slice(0,-2) + "цы";
  if (word === "заяц") return "зайцы";
  if (word === "сосед") return "соседи";
  // Akıcı "о": -ок -> -ки (потолок -> потолки; сок/урок/срок istisna)
  if (word.endsWith("ок") && word !== "сок" && word !== "урок" && word !== "срок") return word.slice(0,-2) + "ки";
  return word + (hard.includes(last) ? "и" : "ы");
}

function russianAdjForms(word: string): { fem: string; neut: string; pl: string } | null {
  if (word.length < 4 || /\s|-/.test(word)) return null;
  const hard = "гкхжшщч";
  if (word.endsWith("ый") || word.endsWith("ой")) {
    const stem = word.slice(0,-2);
    const prev = word[word.length - 3];
    return { fem: stem+"ая", neut: stem+"ое", pl: stem+(hard.includes(prev) ? "ие" : "ые") };
  }
  if (word.endsWith("ий")) {
    const stem = word.slice(0,-2);
    const prev = word[word.length - 3];
    if (hard.includes(prev)) return { fem: stem+"ая", neut: stem+"ое", pl: stem+"ие" };
    return { fem: stem+"яя", neut: stem+"ее", pl: stem+"ие" };
  }
  return null;
}

const IRREGULAR_PAST_RU = new Set(["умереть","тереть","стереть","запереть","отпереть","мочь","печь","беречь","стричь","течь","жечь","лечь","волочь","толочь","помочь"]);

function russianPastForms(word: string): string[] | null {
  if (word.length < 4 || /\s|-/.test(word)) return null;
  if (word.endsWith("ся")) {
    const stem = word.slice(0,-3);
    if (stem.length < 2) return null;
    return [stem+"лся", stem+"лась", stem+"лось", stem+"лись"];
  }
  if (!word.endsWith("ть")) return null;
  if (word.endsWith("сть") || word.endsWith("зть") || word.endsWith("чь") || word.endsWith("йти") || word.endsWith("нуть")) return null;
  if (IRREGULAR_PAST_RU.has(word)) return null;
  const stem = word.slice(0,-2);
  if (stem.length < 2) return null;
  return [stem+"л", stem+"ла", stem+"ло", stem+"ли"];
}

function buildRussianDataset(): VocabularyWord[] {
  const map = new Map<string, RuBaseTuple>();
  for (const t of BASE_TUPLES_RU) {
    const key = t[0].toLowerCase().trim();
    if (!map.has(key)) map.set(key, t);
  }
  const unique = Array.from(map.values());
  const dataset: VocabularyWord[] = [];
  let id = 0;

  const makeWord = (word: string, tr: string, pos: string, level: WordLevel, topic: string): VocabularyWord => {
    const clean = word.trim().toLowerCase();
    return {
      id: id++,
      word: clean,
      meaningTr: tr,
      phonetic: `/${translitRu(clean)}/`,
      pos,
      topic,
      level,
      definition: `Русское слово уровня ${level} (${pos.toUpperCase()}), по-турецки: «${tr}». Тема: ${topic}.`,
      example: `Пример: Я использую слово «${clean}», когда говорю на тему «${topic}».`
    };
  };

  // 1. Tüm benzersiz base (gerçek) kelimeler
  for (const t of unique) {
    if (dataset.length >= 3000) break;
    dataset.push(makeWord(t[0], t[1], t[2], t[3], t[4]));
  }

  // 2. Kurallı gramatik varyantlar (pass'lar halinde dengeli):
  //    pass 0: isim çoğul + sıfat dişil + fiil geçmiş eril
  //    pass 1: sıfat nötr + fiil geçmiş dişil
  //    pass 2: sıfat çoğul + fiil geçmiş nötr
  //    pass 3: fiil geçmiş çoğul
  const addVariant = (w: string, tr: string, pos: string, lvl: WordLevel, topic: string) => {
    if (map.has(w)) return;
    map.set(w, [w, tr, pos, lvl, topic]);
    if (dataset.length < 3000) dataset.push(makeWord(w, tr, pos, lvl, topic));
  };

  let pass = 0;
  while (dataset.length < 3000 && pass < 8) {
    for (const base of unique) {
      const [w, tr, pos, lvl, topic] = base;
      const low = w.toLowerCase().trim();
      if (low.includes(" ") || low.includes("-") || low.includes("(")) continue;
      if (pos === "noun" && pass === 0) {
        const pl = russianPlural(low);
        if (pl && pl !== low) addVariant(pl, getTurkishPluralRu(tr), pos, lvl, topic);
      } else if (pos === "adjective") {
        const f = russianAdjForms(low);
        if (f) {
          if (pass === 0) addVariant(f.fem, tr + " (dişil)", pos, lvl, topic);
          else if (pass === 1) addVariant(f.neut, tr + " (nötr)", pos, lvl, topic);
          else if (pass === 2) addVariant(f.pl, tr + " (çoğul)", pos, lvl, topic);
        }
      } else if (pos === "verb") {
        const p = russianPastForms(low);
        if (p) {
          if (pass === 0) addVariant(p[0], tr + " (geçmiş zaman eril)", pos, lvl, topic);
          else if (pass === 1) addVariant(p[1], tr + " (geçmiş zaman dişil)", pos, lvl, topic);
          else if (pass === 2) addVariant(p[2], tr + " (geçmiş zaman nötr)", pos, lvl, topic);
          else if (pass === 3) addVariant(p[3], tr + " (geçmiş zaman çoğul)", pos, lvl, topic);
        }
      }
    }
    pass++;
  }

  // 3. Garantili 3000 (olmamalı; güvenlik dolgusu)
  let fi = 0;
  while (dataset.length < 3000) {
    const b = unique[fi % unique.length];
    dataset.push(makeWord(b[0], b[1], b[2], b[3], b[4]));
    fi++;
  }

  return dataset.slice(0,3000).map((w,i)=>({...w, id:i}));
}

export const TOTAL_WORDS_RU = 3000;
export const RUSSIAN_PATH: VocabularyWord[] = buildRussianDataset();
